static const z_t6346_t _zag3135 = { { .data = "win_setenv", .size = 10 }, { .length = 1, .data = _zag3134 }, { .length = 1, .data = _zag3107 }, { .data = "static int z_win_setenv(const char* k, size_t kn, const char* v, size_t vn) {\n    wchar_t* wk = z_win_wide(k, kn);\n    wchar_t* wv = wk != NULL ? z_win_wide(v, vn) : NULL;\n    if (wv == NULL) {\n        free(wk);\n        return -1;\n    }\n    BOOL ok = kn > 0 && SetEnvironmentVariableW(wk, wv);\n    DWORD e = kn > 0 ? GetLastError() : ERROR_INVALID_PARAMETER;\n    /* the C runtime takes \"\" as removal; Win32 keeps an empty value */\n    if (ok && vn > 0) _wputenv_s(wk, wv);\n    free(wk);\n    free(wv);\n    SetLastError(e);\n    return ok ? 0 : -1;\n}", .size = 547 } };
